@RequiresApi(Build.VERSION_CODES.VANILLA_ICE_CREAM)
class PowerEfficientBatchWorker(
    context: Context,
    private val targetDurationNanos: Long,
) {
    private val appContext = context.applicationContext
    private val executor = Executors.newSingleThreadExecutor { runnable ->
        Thread(runnable, "pe-batch-worker")
    }
    private val dispatcher = executor.asCoroutineDispatcher()
    private var session: PerformanceHintManager.Session? = null

    init {
        require(targetDurationNanos > 0L)
    }

    suspend fun start(): Boolean = withContext(dispatcher) {
        check(session == null) { "Session has already started" }
        val manager = appContext.getSystemService(PerformanceHintManager::class.java)
        val tid = Process.myTid()
        session = manager?.createHintSession(intArrayOf(tid), targetDurationNanos)
        session?.setPreferPowerEfficiency(true)
        session != null
    }

    suspend fun runCycle(block: () -> Unit) = withContext(dispatcher) {
        val activeSession = checkNotNull(session) { "Call start() before runCycle()" }
        val start = SystemClock.uptimeNanos()
        var workFailure: Throwable? = null
        try {
            block() // 单个周期不挂起、不切换调度器、不把工作移交给其他线程。
        } catch (error: Throwable) {
            workFailure = error
            throw error
        } finally {
            val actual = SystemClock.uptimeNanos() - start
            if (actual > 0L) {
                try {
                    activeSession.reportActualWorkDuration(actual)
                } catch (hintError: RuntimeException) {
                    val original = workFailure
                    if (original != null) original.addSuppressed(hintError)
                    else throw hintError
                }
            }
        }
    }

    suspend fun close() = withContext(NonCancellable) {
        try {
            withContext(dispatcher) {
                session?.close()
                session = null
            }
        } finally {
            dispatcher.close()
            executor.shutdown()
        }
    }
}
